[{"order":1,"type":"heading","text":"Enterprise Folder Structures and Separation of Concerns in Express.js"},{"order":2,"type":"paragraph","text":"When building enterprise-grade applications with Express.js, maintaining a clean and scalable folder structure is critical. Without a well-defined architecture, applications quickly degrade into monolithic, unmaintainable codebases often referred to as spaghetti code."},{"order":3,"type":"subheading","text":"The Principle of Separation of Concerns"},{"order":4,"type":"paragraph","text":"Separation of Concerns (SoC) is a design principle for separating a computer program into distinct sections such that each section addresses a separate concern. In an Express.js application, this means decoupling routing, business logic, data access, and configuration management."},{"order":5,"type":"subheading","text":"Recommended Enterprise Folder Structure"},{"order":6,"type":"paragraph","text":"Below is a battle-tested directory layout designed for large-scale Express.js applications. It adopts a modular or layered approach depending on the system complexity."},{"order":7,"type":"code","text":"/src
  /config
    database.js
    environment.js
  /controllers
    user.controller.js
  /middlewares
    auth.middleware.js
    error.middleware.js
  /models
    user.model.js
  /routes
    v1
      index.js
      user.routes.js
  /services
    user.service.js
  /utils
    logger.js
  app.js
  server.js"},{"order":8,"type":"subheading","text":"Breaking Down the Layers"},{"order":9,"type":"bullet_point","text":"Config: Handles environment variables, database connections, and third-party SDK initializations."},{"order":10,"type":"bullet_point","text":"Routes: Purely responsible for mapping HTTP endpoints to specific controller methods. No business logic should reside here."},{"order":11,"type":"bullet_point","text":"Controllers: Handle HTTP requests and responses. They extract payloads, call appropriate services, and return responses or pass errors to next()."},{"order":12,"type":"bullet_point","text":"Services: Contain the core business logic. They are completely decoupled from Express req and res objects, making them highly reusable and unit-testable."},{"order":13,"type":"bullet_point","text":"Models: Define schemas, interact with the database, and handle data persistence operations."},{"order":14,"type":"subheading","text":"Implementing the Pattern: Service and Controller Example"},{"order":15,"type":"paragraph","text":"Here is an example demonstrating how concerns are separated between a service and a controller."},{"order":16,"type":"code","text":"// services/user.service.js
const UserModel = require('../models/user.model');

class UserService {
  async createUser(userData) {
    // Business logic goes here (e.g., hashing passwords, validation rules)
    const existingUser = await UserModel.findOne({ email: userData.email });
    if (existingUser) {
      throw new Error('User already exists');
    }
    return await UserModel.create(userData);
  }
}

module.exports = new UserService();"},{"order":17,"type":"code","text":"// controllers/user.controller.js
const userService = require('../services/user.service');

class UserController {
  async register(req, res, next) {
    try {
      const user = await userService.createUser(req.body);
      return res.status(201).json({
        success: true,
        data: user
      });
    } catch (error) {
      next(error);
    }
  }
}

module.exports = new UserController();"},{"order":18,"type":"subheading","text":"Conclusion"},{"order":19,"type":"paragraph","text":"By strictly enforcing separation of concerns and keeping a modular folder structure, your Express.js applications will remain maintainable, testable, and ready to scale as your engineering team and product requirements grow."}]
